{
  "id": "50df0d25-b4ab-4b43-b6f5-0c7b5a456d2c",
  "version": "1.8",
  "name": "ExpenseApproval",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "04ef4d80-1829-477f-9a4c-4fc43320b850",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "preparePacket",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Prepare Review Packet"
      },
      "inputs": {
        "script": "const expenseId = $vars.expenseId;\nconst submittedBy = $vars.submittedBy;\nconst amount = $vars.amount;\nconst description = $vars.description;\nreturn {\n  expenseId: expenseId,\n  submittedBy: submittedBy,\n  amount: amount,\n  description: description,\n  summary: `Expense #${expenseId} submitted by ${submittedBy} for $${amount}: ${description}`\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "managerReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Review"
      },
      "inputs": {
        "title": "Expense Report Approval",
        "priority": "Medium",
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
          "fields": [
            {
              "id": "expenseid",
              "label": "Expense ID",
              "type": "text",
              "direction": "input",
              "binding": "vars.preparePacket.output.expenseId"
            },
            {
              "id": "submittedby",
              "label": "Submitted By",
              "type": "text",
              "direction": "input",
              "binding": "vars.preparePacket.output.submittedBy"
            },
            {
              "id": "amount",
              "label": "Amount ($)",
              "type": "number",
              "direction": "input",
              "binding": "vars.preparePacket.output.amount"
            },
            {
              "id": "description",
              "label": "Description",
              "type": "text",
              "direction": "input",
              "binding": "vars.preparePacket.output.description"
            },
            {
              "id": "comments",
              "label": "Manager Comments",
              "type": "text",
              "direction": "output",
              "variable": "vars.managerComments"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "comments": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.managerReview.status === \"Approve\"",
        "trueLabel": "Approved",
